insert into public.role_permissions(role_name,permission_key) values ('admin','dashboard.view'),('admin','menu.manage'),('admin','inventory.manage'),('admin','reports.view'),('admin','staff.manage'),('admin','settings.manage'),('admin','expenses.manage'),('admin','customer_ledger.view'),('manager','dashboard.view'),('manager','menu.manage'),('manager','inventory.manage'),('manager','reports.view'),('manager','expenses.manage'),('manager','customer_ledger.view'),('pos_user','customer_ledger.view') on conflict do nothing; create or replace function public.get_my_permissions() returns table(permission_key text) language sql stable security definer set search_path=public as $$ select distinct rp.permission_key from public.user_roles ur join public.role_permissions rp on rp.role_name=ur.role::text where ur.user_id=auth.uid() union select up.permission_key from public.user_permissions up where up.user_id=auth.uid() and up.is_allowed=true except select up.permission_key from public.user_permissions up where up.user_id=auth.uid() and up.is_allowed=false $$; revoke all on function public.get_my_permissions() from public,anon; grant execute on function public.get_my_permissions() to authenticated;